287	    /**
288	     * Builds the derived identity key that consolidates all owner duplicate detection into a
289	     * single value: the normalized E.164 {@code telephone}, the lower-cased {@code email}
290	     * (empty when none) and the {@code householdId} (empty when the owner shares no household),
291	     * joined by {@code '|'}. Two owners are duplicates exactly when their whole identity keys are
292	     * equal, so a difference in any of the three parts (for example two household mates with
293	     * different telephones) yields distinct keys. A {@code null} part contributes the empty string.
294	     *
295	     * @param telephone the normalized E.164 telephone
296	     * @param email the lower-cased email, or {@code null} when none
297	     * @param householdId the shared household identifier, or {@code null} when none
298	     * @return the derived identity key
299	     */
300	    public static String identityKey(String telephone, String email, String householdId) {
301	        return (telephone == null ? "" : telephone) + "|"
302	            + (email == null ? "" : email) + "|"
303	            + (householdId == null ? "" : householdId);
304	    }
305	
306	    /**
307	     * Returns this owner's derived identity key, see
308	     * {@link #identityKey(String, String, String)}.
309	     *
310	     * @return the derived identity key for this owner
311	     */
312	    @Transient
313	    public String getIdentityKey() {
314	        return identityKey(this.telephone, this.email, this.householdId);
315	    }
316	
317	    /**
318	     * Fixed telephone country-code table: the exact national-number length (the count of digits
319	     * following the country code) each country code this application recognizes admits
320	     * ({@code '61'} Australia => 9, {@code '1'} NANP => 10). Keyed by the country-code digits
321	     * without the leading {@code '+'}. A country code absent from this table is not recognized.
322	     */
323	    private static final Map<String, Integer> COUNTRY_CODE_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
324	
325	    /**
326	     * Resolves the recognized country code a normalized E.164 telephone carries: the longest entry
327	     * of the fixed country-code table (see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}) whose digits the
328	     * number begins with, so a shorter code can never shadow a longer one. Returns the country-code
329	     * digits without the leading {@code '+'} (for example {@code '61'} for {@code '+61412345678'}),
330	     * or {@code null} when the value is {@code null}, carries no leading {@code '+'}, or begins with
331	     * no recognized country code. This is the single definition of how an E.164 telephone splits
332	     * from its country code, shared by every rule that reasons about a telephone's country code.
333	     *
334	     * @param telephone the normalized E.164 telephone (a {@code '+'} followed by digits), or {@code null}
335	     * @return the recognized country-code digits, or {@code null} when none is recognized
336	     */
337	    public static String countryCodeOf(String telephone) {
338	        if (telephone == null || !telephone.startsWith("+")) {
339	            return null;
340	        }
341	        String digits = telephone.substring(1);
342	        return COUNTRY_CODE_NATIONAL_LENGTHS.keySet().stream()
343	            .filter(digits::startsWith)
344	            .max(Comparator.comparingInt(String::length))
345	            .orElse(null);
346	    }
347	
348	    /**
349	     * Resolves the exact national-number length (the count of digits following the country code) a
350	     * recognized country code admits using the fixed country-code table ({@code '61'} => 9,
351	     * {@code '1'} => 10, see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}). Returns the length, or
352	     * {@code null} when the country code is {@code null} or not recognized (it then carries no
353	     * per-country length rule). This is the single definition of the per-country national-number
354	     * lengths, shared by every rule that relates a telephone's national number to its country code.
355	     *
356	     * @param countryCode the country-code digits without the leading {@code '+'}, or {@code null}
357	     * @return the required national-number length, or {@code null} when the code is not recognized
358	     */
359	    public static Integer nationalNumberLength(String countryCode) {
360	        return countryCode == null ? null : COUNTRY_CODE_NATIONAL_LENGTHS.get(countryCode);
361	    }
362	
363	    /**
364	     * Fixed city-to-region table: the canonical region each known city belongs to
365	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). A city
366	     * absent from this table has no known region.
367	     */
368	    private static final Map<String, String> CITY_REGIONS = Map.of(
369	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
370	
371	    /**
372	     * Resolves the canonical region a city belongs to using the fixed city-to-region table
373	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns the
374	     * region string, or {@code null} when the city has no known region. This is the single
375	     * definition of the city-to-region mapping, shared by every rule that derives a region
376	     * from an owner's city.
377	     *
378	     * @param city the city to resolve
379	     * @return the canonical region, or {@code null} when the city has no known region
380	     */
381	    public static String regionForCity(String city) {
382	        return CITY_REGIONS.get(city);
383	    }
384	
385	    /**
386	     * Fixed region-to-postcode table: the inclusive {@code {low, high}} 4-digit postcode range
387	     * each region admits ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
388	     * A region absent from this table has no fixed range.
389	     */
390	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
391	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
392	
393	    /**
394	     * Resolves the inclusive {@code {low, high}} 4-digit postcode range a region admits using the
395	     * fixed region-to-postcode table ({@code NSW 2000-2099}, {@code VIC 3000-3099},
396	     * {@code QLD 4000-4099}). Returns the range, or {@code null} when the region is {@code null} or
397	     * has no fixed range (any 4-digit postcode is then admitted). This is the single definition of
398	     * the region-to-postcode ranges, shared by every rule that relates a postcode to a region.
399	     *
400	     * @param region the region to resolve, or {@code null}
401	     * @return the inclusive {@code {low, high}} range, or {@code null} when the region has none
402	     */
403	    public static int[] postcodeRangeForRegion(String region) {
404	        return region == null ? null : REGION_POSTCODE_RANGES.get(region);
405	    }
406	
407	    /**
408	     * Resolves the canonical region a postcode belongs to by finding the fixed region-to-postcode
409	     * range that contains it ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
410	     * Returns the region string, or {@code null} when the postcode is {@code null}, not a 4-digit
411	     * value, or falls in no known range. This is the single definition of the postcode-to-region
412	     * mapping, shared by every rule that derives a region from a postcode.
413	     *
414	     * @param postcode the postcode to resolve
415	     * @return the canonical region, or {@code null} when the postcode maps to no known region
416	     */
417	    public static String regionForPostcode(String postcode) {
418	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
419	            return null;
420	        }
421	        int value = Integer.parseInt(postcode);
422	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
423	            int[] range = entry.getValue();
424	            if (value >= range[0] && value <= range[1]) {
425	                return entry.getKey();
426	            }
427	        }
428	        return null;
429	    }
430	
431	    /**
432	     * Returns the canonical region this owner belongs to. The owner's {@code postcode} is preferred:
433	     * when it falls in a known region range (see {@link #regionForPostcode(String)}) that region is
434	     * used, disambiguating cities that share a name. Only when the postcode is absent or in no known
435	     * range does derivation fall back to the fixed city-to-region table (see
436	     * {@link #regionForCity(String)}). Returns {@code null} when neither the postcode nor the city
437	     * resolves to a known region. This is the single definition of an owner's region, shared by
438	     * every rule that derives a region from an owner.
439	     *
440	     * @return the owner's canonical region, or {@code null} when it has no known region
441	     */
442	    @Transient
443	    public String getRegion() {
444	        String region = regionForPostcode(this.postcode);
445	        return region != null ? region : regionForCity(this.city);
446	    }
447	
448	    /**
449	     * Resolves whether an {@code email} counts as present for membership purposes: the value is
450	     * non-null and not blank. Returns {@code false} otherwise. This is the single definition of an
451	     * owner "having an email", shared by every rule that turns email presence into a derived value
452	     * (its membership factor and its {@code contactPreference}).
453	     *
454	     * @param email the owner's email, or {@code null}
455	     * @return {@code true} when the email is present and not blank
456	     */
457	    public static boolean hasEmail(String email) {
458	        return email != null && !email.isBlank();
459	    }
460	
461	    /**
462	     * Resolves whether an owner with the given {@code namesakeCount} has no namesakes: the count is
463	     * present and equal to {@code 0}. Returns {@code false} when the count is {@code null} (unknown)
464	     * or positive. This is the single definition of the "no namesakes" membership factor, shared by
465	     * every rule that rewards an owner for being unique by name.
466	     *
467	     * @param namesakeCount the owner's namesake count, or {@code null}
468	     * @return {@code true} when the owner is known to have no namesakes
469	     */
470	    public static boolean hasNoNamesakes(Integer namesakeCount) {
471	        return namesakeCount != null && namesakeCount == 0;
472	    }
473	
474	    /**
475	     * Resolves the fiscal year a date falls in. The fiscal year starts on 1 July, so a date in July
476	     * through December belongs to the fiscal year of the following calendar year, while a date in
477	     * January through June belongs to the fiscal year of its own calendar year (for example both
478	     * 2025-08-01 and 2026-03-01 fall in fiscal year 2026). This is the single definition of the
479	     * date-to-fiscal-year mapping, shared by every value derived on a fiscal-year basis (the
480	     * {@code fiscalYear}, the membership number's year segment and tenure).
481	     *
482	     * @param date the date to resolve, never {@code null}
483	     * @return the fiscal year the date falls in
484	     */
485	    public static int fiscalYearOf(LocalDate date) {
486	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
487	    }
488	
489	    /**
490	     * Resolves whether an owner registered on {@code registrationDate} has long tenure as of
491	     * {@code asOf}: the number of elapsed fiscal years between the two dates (see
492	     * {@link #fiscalYearOf(LocalDate)}) exceeds {@code 1}. Returns {@code false} when
493	     * {@code registrationDate} is absent, so the owner has no derivable tenure; because a newly
494	     * created owner has zero elapsed fiscal years, it never counts as long-tenured. This is the
495	     * single definition of the "long tenure" membership factor, shared by every rule that rewards
496	     * an owner for tenure beyond a fiscal year.
497	     *
498	     * @param registrationDate the owner's registration date, or {@code null}
499	     * @param asOf the date the tenure is measured against
500	     * @return {@code true} when the owner's tenure exceeds one elapsed fiscal year
501	     */
502	    public static boolean hasLongTenure(LocalDate registrationDate, LocalDate asOf) {
503	        return registrationDate != null && fiscalYearOf(asOf) - fiscalYearOf(registrationDate) > 1;
504	    }
505	
506	    /**
507	     * Resolves whether an owner with the given {@code householdMemberCount} belongs to a large
508	     * household: the count is present and at least {@code 3}. Returns {@code false} when the count is
509	     * {@code null} (unknown) or smaller. This is the single definition of the "large household"
510	     * membership factor, shared by every rule that rewards an owner for a household of three or more.
511	     *
512	     * @param householdMemberCount the number of owners sharing the household, or {@code null}
513	     * @return {@code true} when the owner is known to belong to a household of three or more
514	     */
515	    public static boolean hasLargeHousehold(Integer householdMemberCount) {
516	        return householdMemberCount != null && householdMemberCount >= 3;
517	    }
518	
519	    /**
520	     * Returns this owner's membership points. Points start at {@code 0} and accumulate the membership
521	     * factors: {@code 2} when an email is present, {@code 1} when the owner has no namesakes
522	     * (namesakeCount is 0), {@code 2} when the owner belongs to a household of three or more, and
523	     * {@code 3} when the owner's tenure exceeds one elapsed fiscal year. Because a newly created
524	     * owner has zero tenure, the tenure points are never awarded on creation. This is the single source the
525	     * membership level is derived from (see {@link #getMembershipLevel()}).
526	     *
527	     * @return the owner's membership points
528	     */
529	    @Transient
530	    public Integer getMembershipPoints() {
531	        LocalDate today = LocalDate.now();
532	        int points = 0;
533	        if (hasEmail(this.email)) {
534	            points += 2;
535	        }
536	        if (hasNoNamesakes(this.namesakeCount)) {
537	            points += 1;
538	        }
539	        if (hasLargeHousehold(this.householdMemberCount)) {
540	            points += 2;
541	        }
542	        if (hasLongTenure(this.registrationDate, today)) {
543	            points += 3;
544	        }
545	        return points;
546	    }
547	
548	    /**
549	     * Returns this owner's numeric membership level, derived from its membership points (see
550	     * {@link #getMembershipPoints()}): {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3},
551	     * {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more points.
552	     *
553	     * @return the owner's membership level
554	     */
555	    @Transient
556	    public Integer getMembershipLevel() {
557	        int points = getMembershipPoints();
558	        if (points >= 6) {
559	            return 4;
560	        }
561	        if (points >= 4) {
562	            return 3;
563	        }
564	        if (points >= 2) {
565	            return 2;
566	        }
567	        return 1;
568	    }
569	
570	    /**
571	     * Returns this owner's fiscal year formatted as {@code 'FY<YY>'}, where YY is the last two digits
572	     * of the fiscal year (starting 1 July, see {@link #fiscalYearOf(LocalDate)}) the owner's
573	     * business-day-adjusted {@code registrationDate} falls in, e.g. {@code 'FY26'}. Returns
574	     * {@code null} when the owner has no registration date, so the fiscal year cannot be derived.
575	     * This is the single definition of an owner's fiscal year, shared by every value derived on a
576	     * fiscal-year basis (see {@link #getMembershipNumber()}).
577	     *
578	     * @return the owner's fiscal year, or {@code null} when it cannot be derived
579	     */
580	    @Transient
581	    public String getFiscalYear() {
582	        if (this.registrationDate == null) {
583	            return null;
584	        }
585	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
586	    }
587	
588	    /**
589	     * Returns this owner's membership number formatted as {@code '<customerCode>-M<YY>'}, where YY is
590	     * the last two digits of the fiscal year (see {@link #fiscalYearOf(LocalDate)}) the owner's
591	     * business-day-adjusted {@code registrationDate} falls in, e.g. {@code 'NSW-A1B2C3D4-M26'}.
592	     * Returns {@code null} when the owner has no customer code or registration date.
593	     *
594	     * @return the owner's membership number, or {@code null} when it cannot be derived
595	     */
596	    @Transient
597	    public String getMembershipNumber() {
598	        if (this.customerCode == null || this.registrationDate == null) {
599	            return null;
600	        }
601	        return String.format("%s-M%02d", this.customerCode, fiscalYearOf(this.registrationDate) % 100);
602	    }
603	
604	    /**
605	     * Returns this owner's check digit: a single Luhn check digit (0-9) over the digits contained in
606	     * the owner's customerCode. Returns {@code null} when the owner has no customer code.
607	     *
608	     * @return the owner's check digit, or {@code null} when it has no customer code
609	     */
610	    @Transient
611	    public Integer getCheckDigit() {
612	        if (this.customerCode == null) {
613	            return null;
614	        }
615	        String code = this.customerCode;
616	        int sum = 0;
617	        boolean dbl = true;
618	        for (int i = code.length() - 1; i >= 0; i--) {
619	            char c = code.charAt(i);
620	            if (c < '0' || c > '9') {
621	                continue;
622	            }
623	            int d = c - '0';
624	            if (dbl) {
625	                d *= 2;
626	                if (d > 9) {
627	                    d -= 9;
628	                }
629	            }
630	            sum += d;
631	            dbl = !dbl;
632	        }
633	        return (10 - (sum % 10)) % 10;
634	    }
635	
636	    /**
637	     * Returns this owner's age band, derived from {@code birthDate} computed against
638	     * {@code registrationDate}: the whole number of years between the two dates places the owner in
639	     * {@code 'MINOR'} (under 18), {@code 'ADULT'} (18 to 64 inclusive) or {@code 'SENIOR'} (65 or
640	     * older). Returns {@code null} when the owner has no birth date or no registration date, so the
641	     * band cannot be derived. This is the single definition of an owner's age band.
642	     *
643	     * @return the owner's age band, or {@code null} when it cannot be derived
644	     */
645	    @Transient
646	    public String getAgeBand() {
647	        if (this.birthDate == null || this.registrationDate == null) {
648	            return null;
649	        }
650	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
651	        if (age < 18) {
652	            return "MINOR";
653	        }
654	        if (age < 65) {
655	            return "ADULT";
656	        }
657	        return "SENIOR";
658	    }
659	
660	    protected Set<Pet> getPetsInternal() {
661	        if (this.pets == null) {
662	            this.pets = new HashSet<>();
663	        }
664	        return this.pets;
665	    }
666	
667	    protected void setPetsInternal(Set<Pet> pets) {
668	        this.pets = pets;
669	    }
670	
671	    public List<Pet> getPets() {
672	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
673	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
674	        return Collections.unmodifiableList(sortedPets);
675	    }
676	
677	    public void setPets(List<Pet> pets) {
678	        this.pets = new HashSet<>(pets);
679	    }
680	
681	    public void addPet(Pet pet) {
682	        getPetsInternal().add(pet);
683	        pet.setOwner(this);
684	    }
685	
686	    /**
687	     * Return the Pet with the given name, or null if none found for this Owner.
688	     *
689	     * @param name to test
690	     * @return true if pet name is already in use
691	     */
692	    public Pet getPet(String name) {
693	        return getPet(name, false);
694	    }
695	
696	    /**
697	     * Return the Pet with the given name, or null if none found for this Owner.
698	     *
699	     * @param name to test
700	     * @return true if pet name is already in use
701	     */
702	    public Pet getPet(String name, boolean ignoreNew) {
703	        name = name.toLowerCase();
704	        for (Pet pet : getPetsInternal()) {
705	            if (!ignoreNew || !pet.isNew()) {
706	                String compName = pet.getName();
707	                compName = compName.toLowerCase();
708	                if (compName.equals(name)) {
709	                    return pet;
710	                }
711	            }
712	        }
713	        return null;
714	    }
715	
716	    public Pet getPet(Integer petId) {
717	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
718	    }
719	
720	    @Override
721	    public String toString() {
722	        return new ToStringCreator(this)
723	
724	            .append("id", this.getId())
725	            .append("new", this.isNew())
726	            .append("lastName", this.getLastName())
727	            .append("firstName", this.getFirstName())
728	            .append("address", this.address)
729	            .append("city", this.city)
730	            .append("telephone", this.telephone)
731	            .append("email", this.email)
732	            .toString();
733	    }
734	}
