137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
140	        String idempotencyKey = idempotencyKey();
141	        if (idempotencyKey != null) {
142	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
143	            if (replay != null) {
144	                return replay;
145	            }
146	        }
147	        Owner owner = createOwner(ownerFieldsDto);
148	        if (idempotencyKey != null) {
149	            IDEMPOTENT_CREATES.put(idempotencyKey, owner.getId());
150	        }
151	        return createdOwnerResponse(owner);
152	    }
153	
154	    /**
155	     * Reads the request's {@code Idempotency-Key} header, returning the trimmed key or {@code null}
156	     * when the header is absent or blank. A blank key carries no intent to deduplicate, so the
157	     * create proceeds normally.
158	     *
159	     * @return the non-blank idempotency key, or {@code null} when none was supplied
160	     */
161	    private String idempotencyKey() {
162	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
163	        if (key == null || key.isBlank()) {
164	            return null;
165	        }
166	        return key.trim();
167	    }
168	
169	    /**
170	     * Replays the create originally produced by the given {@code Idempotency-Key}, if any: when the
171	     * key has already created an owner that still exists, that owner is rendered with {@code 200 OK}
172	     * (rather than creating a duplicate with {@code 201 Created}). When the key has not been seen, or
173	     * the owner it created no longer exists, {@code null} is returned so the caller creates the owner
174	     * normally.
175	     *
176	     * @param idempotencyKey the non-blank idempotency key supplied on the request
177	     * @return the {@code 200 OK} response carrying the originally created owner, or {@code null}
178	     */
179	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
180	        Integer existingId = IDEMPOTENT_CREATES.get(idempotencyKey);
181	        if (existingId == null) {
182	            return null;
183	        }
184	        Owner existing = this.clinicService.findOwnerById(existingId);
185	        if (existing == null) {
186	            return null;
187	        }
188	        existing.setHouseholdMemberCount(countHouseholdMembers(existing.getHouseholdId()));
189	        OwnerDto ownerDto = ownerMapper.toOwnerDto(existing);
190	        ownerDto.setBulkSignupWarning(bulkSignupWarning(existing.getRegistrationDate()));
191	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
192	    }
193	
194	    /**
195	     * Runs the full intake pipeline for a newly submitted owner and persists the result, returning
196	     * the saved {@link Owner}. The submitted fields are normalized and validated
197	     * ({@link #prepareNewOwner(OwnerFieldsDto, LocalDate)}) against the effective business-day
198	     * {@code registrationDate} ({@link #effectiveRegistrationDate(OwnerFieldsDto)}); the owner is
199	     * then mapped, stamped with that registration date and every derived value (customer code,
200	     * namesake count, household), flagged as a possible duplicate where applicable, saved, and
201	     * finally stamped with its household member count. A rule that rejects the owner signals it by
202	     * throwing, which the exception advice renders as the matching 4xx response, so this method
203	     * returns only for an owner that was accepted and persisted. The create is audited once the
204	     * owner has its identity.
205	     *
206	     * <p>The returned owner carries its generated id and every stored field, ready to be rendered by
207	     * {@link #createdOwnerResponse(Owner)}.
208	     *
209	     * @param ownerFieldsDto the submitted owner fields, normalized in place
210	     * @return the persisted owner
211	     */
212	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
213	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto);
214	        prepareNewOwner(ownerFieldsDto, registrationDate);
215	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
216	        owner.setRegistrationDate(registrationDate);
217	        owner.setCustomerCode(customerCodeFor(owner));
218	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
219	        assignHousehold(owner);
220	        applyPossibleDuplicate(owner, ownerFieldsDto);
221	        this.clinicService.saveOwner(owner);
222	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
223	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
224	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
225	            owner.getMembershipLevel(), owner.getMembershipNumber());
226	        return owner;
227	    }
228	
229	    /**
230	     * Renders a persisted owner as the {@code 201 Created} response of the create endpoint. The owner
231	     * is mapped to an {@link OwnerDto}, its {@code bulkSignupWarning} is derived from the owner's
232	     * stored {@code registrationDate} (mirroring {@link #getOwner(Integer)}), and a {@code Location}
233	     * header pointing at {@code /api/owners/{id}} is attached. Isolating the response assembly here
234	     * keeps {@link #addOwner(OwnerFieldsDto)} a thin orchestration of "create the owner, then render
235	     * it" and gives the created representation one place to grow.
236	     *
237	     * @param owner the persisted owner to render, carrying its generated id and stored fields
238	     * @return the {@code 201 Created} response carrying the owner representation and {@code Location} header
239	     */
240	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
241	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
242	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
243	        HttpHeaders headers = new HttpHeaders();
244	        headers.setLocation(UriComponentsBuilder.newInstance()
245	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
246	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
247	    }
