541	    /**
542	     * Builds the customer code assigned to a newly created owner. The code is formatted as
543	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the owner's canonical region (see
544	     * {@link Owner#getRegion()}), rendered {@code 'UNKNOWN'} when the owner has no known region,
545	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest over the
546	     * owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}. The code
547	     * carries no sequence number, so two owners sharing a region, telephone and last name resolve to
548	     * the same code. The whole owner is taken so the code is derived from whichever of its fields the
549	     * identity scheme needs.
550	     *
551	     * @param owner the owner being created, whose fields the code is derived from
552	     * @return the formatted customer code
553	     */
554	    private String customerCodeFor(Owner owner) {
555	        String region = owner.getRegion();
556	        String regionCode = region != null ? region : "UNKNOWN";
557	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
558	        return deduplicateCustomerCode(regionCode + "-" + hash8);
559	    }
560	
561	    /**
562	     * Ensures the computed {@code customerCode} is unique across existing owners. When the given base
563	     * code collides with an existing owner's {@code customerCode}, {@code '-<n>'} is appended with the
564	     * smallest {@code n} of 2 or more that yields a code no existing owner already carries.
565	     *
566	     * @param baseCode the customer code computed for the owner being created
567	     * @return the base code when it is already unique, otherwise the de-duplicated code
568	     */
569	    private String deduplicateCustomerCode(String baseCode) {
570	        Set<String> existing = this.clinicService.findAllOwners().stream()
571	            .map(Owner::getCustomerCode)
572	            .filter(Objects::nonNull)
573	            .collect(Collectors.toSet());
574	        if (!existing.contains(baseCode)) {
575	            return baseCode;
576	        }
577	        int n = 2;
578	        while (existing.contains(baseCode + "-" + n)) {
579	            n++;
580	        }
581	        return baseCode + "-" + n;
582	    }
