601	    /**
602	     * Flags a newly created owner as a possible (soft) duplicate. Reaching this point means the
603	     * owner already cleared {@link #rejectDuplicateIdentity(OwnerFieldsDto)}, so it is not a hard
604	     * household duplicate. A member that declared its household via {@code sharesHousehold} is a
605	     * deliberate addition to a known household, not a suspected duplicate, so it is never flagged.
606	     * Otherwise it is a possible duplicate when an existing owner shares its {@code lastName}
607	     * (compared case-insensitively) and its {@code postcode} while carrying a different (normalized)
608	     * {@code telephone}. When such an owner is found, {@code possibleDuplicate} is set {@code true}
609	     * and {@code possibleDuplicateOf} to the matching owner's id; otherwise {@code possibleDuplicate}
610	     * is set {@code false} and no matching id is recorded. An owner without a postcode can share no
611	     * postcode and is never a possible duplicate.
612	     *
613	     * @param owner the owner being created, already carrying its normalized telephone and postcode
614	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
615	     */
616	    private void applyPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
617	        owner.setPossibleDuplicate(false);
618	        owner.setPossibleDuplicateOf(null);
619	        if (sharesHousehold(ownerFieldsDto)) {
620	            return;
621	        }
622	        findPossibleDuplicate(owner).ifPresent(existing -> {
623	            owner.setPossibleDuplicate(true);
624	            owner.setPossibleDuplicateOf(existing.getId());
625	        });
626	    }
