776	    /**
777	     * Reduces an email to the canonical form used both to store it and to compare it against
778	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
779	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
780	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
781	     * value read back off an existing owner without risk of rejecting it. This is the single
782	     * definition of email identity: two emails denote the same address exactly when they
783	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
784	     * an email already on an existing owner can be compared for equality after both pass through
785	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
786	     *
787	     * @param email the email to canonicalize, or {@code null} when none was supplied
788	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
789	     */
790	    private String canonicalEmail(String email) {
791	        if (email == null) {
792	            return null;
793	        }
794	        return email.trim().toLowerCase(java.util.Locale.ROOT);
795	    }
