797	    /**
798	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
799	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
800	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
801	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
802	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
803	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
804	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
805	     * 400 response naming the {@code postcode} field.
806	     *
807	     * @param postcode the submitted postcode, or {@code null} when omitted
808	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
809	     */
810	    private void validatePostcode(String postcode, String city) {
811	        if (postcode == null) {
812	            return;
813	        }
814	        if (!postcode.matches("^[0-9]{4}$")) {
815	            throw new InvalidFieldsException(List.of("postcode"));
816	        }
817	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
818	        if (range != null) {
819	            int value = Integer.parseInt(postcode);
820	            if (value < range[0] || value > range[1]) {
821	                throw new InvalidFieldsException(List.of("postcode"));
822	            }
823	        }
824	    }
