828	     * household is keyed on {@code (lastName, postcode)} and identified by the deterministic
829	     * {@code householdId} the owner would receive (see {@link #householdIdFor(String, String)}), so
830	     * two owners sharing a last name and postcode belong to the same household. When any existing
831	     * owner already carries that household identifier the new owner is a household duplicate and a
832	     * {@link DuplicateIdentityException} is thrown, which the exception advice renders as a 409
833	     * Conflict response. Setting {@code sharesHousehold} declares the owner a deliberate member of
834	     * that household and bypasses this block, so it is created rather than rejected. An owner without
835	     * a postcode belongs to no shared household and is never a household duplicate.
836	     *
837	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
838	     */
839	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
840	        if (sharesHousehold(ownerFieldsDto)) {
841	            return;
842	        }
843	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
844	        if (householdId == null) {
845	            return;
846	        }
847	        boolean taken = this.clinicService.findAllOwners().stream()
848	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
849	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
850	        if (taken) {
851	            throw new DuplicateIdentityException(householdId);
852	        }
