901	    /**
902	     * Builds the canonical household key that identifies the household a {@code lastName} and
903	     * {@code postcode} belong to: the normalized last name (case-insensitive, with collapsed
904	     * whitespace) joined to the postcode by {@code '|'}. This is the single definition of which
905	     * owner fields make up a household and how they are normalized;
906	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
907	     * owners in the same household resolve to the same key and therefore the same identifier.
908	     *
909	     * @param lastName the household's last name
910	     * @param postcode the household's postcode
911	     * @return the normalized household key
912	     */
913	    private String householdKey(String lastName, String postcode) {
914	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|" + postcode;
915	    }
916	
917	    /**
918	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
919	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
920	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
921	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
922	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
923	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
924	     * an {@link IllegalStateException} is thrown.
925	     *
926	     * @param input the string to hash
927	     * @param hexChars the number of leading upper-case hex characters to return
928	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
929	     */
930	    private String shaHex(String input, int hexChars) {
931	        try {
932	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
933	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
934	            StringBuilder sb = new StringBuilder();
935	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
936	                sb.append(String.format("%02X", digest[i]));
937	            }
938	            return sb.substring(0, hexChars);
939	        }
940	        catch (java.security.NoSuchAlgorithmException e) {
941	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
942	        }
943	    }
944	
945	    /**
946	     * Counts the owners that belong to the household identified by the given {@code householdId},
947	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
948	     * of owners, so after a create it reflects the household's size including the newly persisted
949	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
950	     * household and yields {@code 0}.
951	     *
952	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
953	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
954	     */
955	    private int countHouseholdMembers(String householdId) {
956	        if (householdId == null) {
957	            return 0;
958	        }
959	        return (int) this.clinicService.findAllOwners().stream()
960	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
961	            .count();
962	    }
963	
964	    /**
965	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
966	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
967	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
968	     *
969	     * @param value the value to collapse, or {@code null}
970	     * @return the whitespace-collapsed value, never {@code null}
971	     */
972	    private String collapseWhitespace(String value) {
973	        if (value == null) {
974	            return "";
975	        }
976	        return value.trim().replaceAll("\\s+", " ");
977	    }
978	
979	    /**
980	     * Common street-type abbreviations expanded during address normalization, keyed by their
981	     * upper-cased token.
982	     */
983	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
984	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
985	
986	    /**
987	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
988	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
989	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
990	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
991	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
992	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
993	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
994	     * everywhere an address is stored or compared.
995	     *
996	     * @param address the submitted address value, or {@code null}
997	     * @return the normalized address, never {@code null}
998	     */
999	    private String normalizeAddress(String address) {
1000	        if (address == null) {
1001	            return "";
1002	        }
1003	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
1004	        if (collapsed.isEmpty()) {
1005	            return "";
1006	        }
1007	        String[] tokens = collapsed.split(" ");
1008	        StringBuilder sb = new StringBuilder(collapsed.length());
1009	        for (int i = 0; i < tokens.length; i++) {
1010	            if (i > 0) {
1011	                sb.append(' ');
1012	            }
1013	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1014	        }
1015	        return sb.toString();
1016	    }
1017	}
